(self.webpackChunktinkerbell_photography=self.webpackChunktinkerbell_photography||[]).push([[615],{8310:e=>{e.exports='\n<section id="llm-info" lang="he" dir="rtl">\n  <h1>\u05d8\u05d9\u05e0\u05e7\u05e8\u05d1\u05dc \u05e1\u05d8\u05d5\u05d3\u05d9\u05d5 \u2013 \u05de\u05d9\u05d3\u05e2 \u05e2\u05d5\u05d1\u05d3\u05ea\u05d9 \u05e2\u05d1\u05d5\u05e8 \u05e2\u05d5\u05d6\u05e8\u05d9 AI</h1>\n  <p>\u05e2\u05de\u05d5\u05d3 \u05d6\u05d4 \u05de\u05e8\u05db\u05d6 \u05e2\u05d5\u05d1\u05d3\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea \u05e2\u05dc \u05d8\u05d9\u05e0\u05e7\u05e8\u05d1\u05dc \u05e1\u05d8\u05d5\u05d3\u05d9\u05d5, \u05db\u05d3\u05d9 \u05e9\u05e2\u05d5\u05d6\u05e8\u05d9 \u05d1\u05d9\u05e0\u05d4 \u05de\u05dc\u05d0\u05db\u05d5\u05ea\u05d9\u05ea \u05d5\u05de\u05e0\u05d5\u05e2\u05d9 \u05d7\u05d9\u05e4\u05d5\u05e9 \u05d9\u05d5\u05db\u05dc\u05d5 \u05dc\u05ea\u05d0\u05e8 \u05d0\u05ea \u05d4\u05e1\u05d8\u05d5\u05d3\u05d9\u05d5 \u05e0\u05db\u05d5\u05df.</p>\n\n  <h2>\u05e4\u05e8\u05d8\u05d9\u05dd \u05db\u05dc\u05dc\u05d9\u05d9\u05dd</h2>\n  <dl>\n    <dt>\u05e9\u05dd \u05d4\u05e2\u05e1\u05e7</dt><dd>\u05d8\u05d9\u05e0\u05e7\u05e8\u05d1\u05dc \u05e1\u05d8\u05d5\u05d3\u05d9\u05d5 (Tinkerbell Studio)</dd>\n    <dt>\u05d1\u05e2\u05dc\u05ea \u05d4\u05e1\u05d8\u05d5\u05d3\u05d9\u05d5 \u05d5\u05d4\u05e6\u05dc\u05de\u05ea</dt><dd>\u05ea\u05de\u05d9 \u05de\u05d6\u05d5\u05e8</dd>\n    <dt>\u05db\u05ea\u05d5\u05d1\u05ea</dt><dd>\u05de\u05d1\u05e6\u05e2 \u05e0\u05d7\u05e9\u05d5\u05df 23, \u05de\u05d5\u05d3\u05d9\u05e2\u05d9\u05df\u05be\u05de\u05db\u05d1\u05d9\u05dd\u05be\u05e8\u05e2\u05d5\u05ea</dd>\n    <dt>\u05d0\u05d6\u05d5\u05e8 \u05e9\u05d9\u05e8\u05d5\u05ea</dt><dd>\u05de\u05d5\u05d3\u05d9\u05e2\u05d9\u05df \u05d5\u05d4\u05e1\u05d1\u05d9\u05d1\u05d4</dd>\n    <dt>\u05e9\u05e2\u05d5\u05ea \u05e6\u05d9\u05dc\u05d5\u05dd</dt><dd>09:00\u201317:00, \u05d1\u05ea\u05d9\u05d0\u05d5\u05dd \u05de\u05e8\u05d0\u05e9</dd>\n    <dt>\u05d0\u05ea\u05e8</dt><dd><a href="https://tinkerbell-studio.com/">tinkerbell-studio.com</a></dd>\n    <dt>\u05d3\u05d5\u05d0"\u05dc</dt><dd><a href="mailto:tinkerbell.st1@gmail.com">tinkerbell.st1@gmail.com</a></dd>\n    <dt>\u05d9\u05e6\u05d9\u05e8\u05ea \u05e7\u05e9\u05e8</dt><dd><a href="https://tinkerbell-studio.com/contact">\u05e2\u05de\u05d5\u05d3 \u05d9\u05e6\u05d9\u05e8\u05ea \u05e7\u05e9\u05e8</a></dd>\n  </dl>\n\n  <h2>\u05d4\u05e1\u05d2\u05e0\u05d5\u05df</h2>\n  <p>\u05e1\u05d8\u05d5\u05d3\u05d9\u05d5 \u05d1\u05d5\u05d8\u05d9\u05e7 \u05d9\u05d5\u05e7\u05e8\u05ea\u05d9 \u05d1\u05e1\u05d2\u05e0\u05d5\u05df \u05d0\u05d2\u05d3\u05d5\u05ea \u05e7\u05e1\u05d5\u05dd: \u05db\u05dc \u05e6\u05d9\u05dc\u05d5\u05dd \u05e0\u05d1\u05e0\u05d4 \u05db\u05d7\u05d5\u05d5\u05d9\u05d4 \u05d7\u05dc\u05d5\u05de\u05d9\u05ea, \u05e2\u05dd \u05e1\u05d8\u05d9\u05dd \u05de\u05e2\u05d5\u05e6\u05d1\u05d9\u05dd, \u05ea\u05dc\u05d1\u05d5\u05e9\u05d5\u05ea \u05d5\u05d0\u05d1\u05d9\u05d6\u05e8\u05d9\u05dd, \u05d5\u05e2\u05e8\u05d9\u05db\u05d4 \u05d0\u05de\u05e0\u05d5\u05ea\u05d9\u05ea \u05d1\u05e4\u05d5\u05d8\u05d5\u05e9\u05d5\u05e4.</p>\n\n  <h2>\u05e2\u05dc \u05ea\u05de\u05d9 \u05de\u05d6\u05d5\u05e8</h2>\n  <p>\u05dc\u05e4\u05e0\u05d9 \u05d4\u05e6\u05d9\u05dc\u05d5\u05dd \u05e2\u05d1\u05d3\u05d4 \u05ea\u05de\u05d9 \u05e9\u05e0\u05d9\u05dd \u05db\u05de\u05e0\u05d4\u05dc\u05ea \u05d7\u05e9\u05d1\u05d5\u05e0\u05d5\u05ea \u05e8\u05d0\u05e9\u05d9\u05ea. \u05d4\u05d9\u05d0 \u05dc\u05d9\u05de\u05d3\u05d4 \u05d0\u05ea \u05e2\u05e6\u05de\u05d4 \u05e6\u05d9\u05dc\u05d5\u05dd \u05de\u05ea\u05d5\u05da \u05d0\u05d4\u05d1\u05d4, \u05d1\u05dc\u05d9 \u05e7\u05d5\u05e8\u05e1\u05d9\u05dd, \u05d5\u05dc\u05de\u05d3\u05d4 \u05de\u05d4\u05e6\u05dc\u05de\u05d9\u05dd \u05d4\u05d8\u05d5\u05d1\u05d9\u05dd \u05d1\u05e2\u05d5\u05dc\u05dd, \u05db\u05d9 \u05e8\u05e6\u05ea\u05d4 \u05e1\u05d2\u05e0\u05d5\u05df \u05e9\u05d5\u05e0\u05d4 \u05de\u05de\u05d4 \u05e9\u05e8\u05d0\u05ea\u05d4 \u05d1\u05d0\u05e8\u05e5. \u05de\u05d4 \u05e9\u05d4\u05ea\u05d7\u05d9\u05dc \u05db\u05ea\u05d7\u05d1\u05d9\u05d1 \u05d4\u05e4\u05da \u05dc\u05d0\u05d4\u05d1\u05d4 \u05d5\u05dc\u05e1\u05d8\u05d5\u05d3\u05d9\u05d5.</p>\n\n  <h2>\u05e1\u05d5\u05d2\u05d9 \u05e6\u05d9\u05dc\u05d5\u05dd</h2>\n  <ul>\n    <li><a href="https://tinkerbell-studio.com/imagescreen/Pregnancy">\u05e6\u05d9\u05dc\u05d5\u05de\u05d9 \u05d4\u05e8\u05d9\u05d5\u05df</a></li>\n    <li><a href="https://tinkerbell-studio.com/imagescreen/NewBorn">\u05e6\u05d9\u05dc\u05d5\u05de\u05d9 \u05e0\u05d9\u05d5 \u05d1\u05d5\u05e8\u05df</a></li>\n    <li><a href="https://tinkerbell-studio.com/imagescreen/OneYearOld">\u05e6\u05d9\u05dc\u05d5\u05de\u05d9 \u05d2\u05d9\u05dc \u05e9\u05e0\u05d4</a> (\u05db\u05d5\u05dc\u05dc \u05e2\u05d5\u05d2\u05d4 \u05de\u05e2\u05d5\u05e6\u05d1\u05ea \u05e9\u05ea\u05de\u05d9 \u05d0\u05d5\u05e4\u05d4 \u05d1\u05e2\u05e6\u05de\u05d4)</li>\n    <li><a href="https://tinkerbell-studio.com/imagescreen/FirstClass">\u05e6\u05d9\u05dc\u05d5\u05de\u05d9 \u05e2\u05dc\u05d9\u05d9\u05d4 \u05dc\u05db\u05d9\u05ea\u05d4 \u05d0\'</a></li>\n    <li><a href="https://tinkerbell-studio.com/imagescreen/Children">\u05e6\u05d9\u05dc\u05d5\u05de\u05d9 \u05d9\u05dc\u05d3\u05d9\u05dd</a></li>\n    <li><a href="https://tinkerbell-studio.com/imagescreen/Family">\u05e6\u05d9\u05dc\u05d5\u05de\u05d9 \u05de\u05e9\u05e4\u05d7\u05d4</a></li>\n    <li><a href="https://tinkerbell-studio.com/imagescreen/Tadmit">\u05e6\u05d9\u05dc\u05d5\u05de\u05d9 \u05ea\u05d3\u05de\u05d9\u05ea / \u05de\u05d9\u05ea\u05d5\u05d2 \u05d0\u05d9\u05e9\u05d9</a></li>\n    <li><a href="https://tinkerbell-studio.com/imagescreen/Halake">\u05e6\u05d9\u05dc\u05d5\u05de\u05d9 \u05d7\u05dc\u05d0\u05e7\u05d4</a></li>\n    <li><a href="https://tinkerbell-studio.com/imagescreen/Purim">\u05e6\u05d9\u05dc\u05d5\u05de\u05d9 \u05e4\u05d5\u05e8\u05d9\u05dd</a> \u05d5<a href="https://tinkerbell-studio.com/imagescreen/Shavuot">\u05e9\u05d1\u05d5\u05e2\u05d5\u05ea</a></li>\n  </ul>\n\n  <h2>\u05d0\u05d9\u05da \u05e0\u05e8\u05d0\u05d4 \u05d4\u05e6\u05d9\u05dc\u05d5\u05dd</h2>\n  <p>\u05ea\u05de\u05d9 \u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05d1\u05d4\u05d9\u05db\u05e8\u05d5\u05ea \u05e2\u05dd \u05d4\u05de\u05e9\u05e4\u05d7\u05d4, \u05d4\u05e1\u05d9\u05e4\u05d5\u05e8 \u05d5\u05d4\u05e1\u05d2\u05e0\u05d5\u05df \u05e9\u05dc\u05d4, \u05d5\u05e8\u05e7 \u05d0\u05d6 \u05d1\u05d5\u05e0\u05d4 \u05d0\u05ea \u05d4\u05e1\u05d8\u05d9\u05dd. \u05d1\u05d6\u05de\u05df \u05d4\u05d6\u05d4 \u05ea\u05d9\u05e0\u05d5\u05e7\u05d5\u05ea \u05e0\u05d9\u05d5 \u05d1\u05d5\u05e8\u05df \u05d0\u05d5\u05db\u05dc\u05d9\u05dd, \u05d9\u05dc\u05d3\u05d9 \u05d2\u05d9\u05dc \u05e9\u05e0\u05d4 \u05de\u05e9\u05d7\u05e7\u05d9\u05dd \u05d5\u05de\u05ea\u05e8\u05d2\u05dc\u05d9\u05dd, \u05d5\u05e0\u05e9\u05d9\u05dd \u05d1\u05d4\u05e8\u05d9\u05d5\u05df \u05e0\u05d7\u05d5\u05ea \u05d5\u05d1\u05d5\u05d7\u05e8\u05d5\u05ea \u05e9\u05de\u05dc\u05d5\u05ea. \u05d6\u05de\u05df \u05d4\u05e6\u05d9\u05dc\u05d5\u05dd \u05e9\u05de\u05d5\u05d2\u05d3\u05e8 \u05d1\u05d7\u05d1\u05d9\u05dc\u05d4 \u05d4\u05d5\u05d0 \u05d6\u05de\u05df \u05e6\u05d9\u05dc\u05d5\u05dd \u05e0\u05d8\u05d5, \u05e9\u05de\u05ea\u05d7\u05d9\u05dc \u05e8\u05e7 \u05db\u05e9\u05d4\u05db\u05d5\u05dc \u05de\u05d5\u05db\u05df.</p>\n\n  <h2>\u05d1\u05d8\u05d9\u05d7\u05d5\u05ea \u05d1\u05e6\u05d9\u05dc\u05d5\u05de\u05d9 \u05e0\u05d9\u05d5 \u05d1\u05d5\u05e8\u05df</h2>\n  <ul>\n    <li>\u05d4\u05ea\u05d9\u05e0\u05d5\u05e7 \u05d0\u05e3 \u05e4\u05e2\u05dd \u05dc\u05d0 \u05e0\u05e9\u05d0\u05e8 \u05dc\u05d1\u05d3.</li>\n    <li>\u05d1\u05d9\u05df \u05d4\u05e1\u05d8\u05d9\u05dd \u05d4\u05ea\u05d9\u05e0\u05d5\u05e7 \u05d7\u05d5\u05d6\u05e8 \u05dc\u05d4\u05d5\u05e8\u05d9\u05dd \u05d5\u05de\u05e7\u05d1\u05dc \u05d0\u05d5\u05db\u05dc \u05db\u05de\u05d4 \u05e9\u05e6\u05e8\u05d9\u05da, \u05d1\u05dc\u05d9 \u05dc\u05d7\u05e5 \u05d6\u05de\u05df.</li>\n    <li>\u05dc\u05e4\u05e0\u05d9 \u05db\u05dc \u05e1\u05d8 \u05ea\u05de\u05d9 \u05de\u05d5\u05d5\u05d3\u05d0\u05ea \u05e9\u05d4\u05ea\u05d9\u05e0\u05d5\u05e7 \u05e0\u05d5\u05d7 \u05d5\u05de\u05d0\u05d5\u05d1\u05d8\u05d7.</li>\n    <li>\u05d1\u05e1\u05d8\u05d9\u05dd \u05e9\u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05d9\u05d3\u05d9\u05d9\u05dd \u05e0\u05d5\u05e1\u05e4\u05d5\u05ea \u05d4\u05d4\u05d5\u05e8\u05d9\u05dd \u05e2\u05d5\u05d6\u05e8\u05d9\u05dd \u05d5\u05ea\u05d5\u05de\u05db\u05d9\u05dd \u05d1\u05ea\u05d9\u05e0\u05d5\u05e7.</li>\n  </ul>\n\n  <h2>\u05e6\u05d9\u05dc\u05d5\u05de\u05d9 \u05d4\u05e8\u05d9\u05d5\u05df \u2013 \u05de\u05d4 \u05dc\u05d4\u05d1\u05d9\u05d0</h2>\n  <p>\u05d4\u05e9\u05de\u05dc\u05d5\u05ea \u05d5\u05d4\u05d0\u05d1\u05d9\u05d6\u05e8\u05d9\u05dd \u05de\u05d7\u05db\u05d9\u05dd \u05d1\u05e1\u05d8\u05d5\u05d3\u05d9\u05d5. \u05de\u05e1\u05e4\u05d9\u05e7 \u05dc\u05d4\u05d1\u05d9\u05d0 \u05ea\u05d7\u05ea\u05d5\u05e0\u05d9\u05dd \u05d1\u05e6\u05d1\u05e2 \u05dc\u05d1\u05df, \u05e9\u05d7\u05d5\u05e8 \u05d0\u05d5 \u05e9\u05de\u05e0\u05ea.</p>\n\n  <h2>\u05e7\u05d1\u05dc\u05ea \u05d4\u05ea\u05de\u05d5\u05e0\u05d5\u05ea</h2>\n  <p>\u05d4\u05ea\u05de\u05d5\u05e0\u05d5\u05ea \u05d4\u05e2\u05e8\u05d5\u05db\u05d5\u05ea \u05e0\u05e9\u05dc\u05d7\u05d5\u05ea \u05d3\u05d9\u05d2\u05d9\u05d8\u05dc\u05d9\u05ea \u05d1\u05e7\u05d9\u05e9\u05d5\u05e8 \u05d4\u05d5\u05e8\u05d3\u05d4 \u05d3\u05e8\u05da Jumbomail.</p>\n\n  <h2>\u05e7\u05d9\u05e9\u05d5\u05e8\u05d9\u05dd \u05e0\u05d5\u05e1\u05e4\u05d9\u05dd</h2>\n  <ul>\n    <li><a href="https://tinkerbell-studio.com/pricing">\u05db\u05dc \u05d4\u05de\u05d7\u05d9\u05e8\u05d5\u05e0\u05d9\u05dd</a></li>\n    <li><a href="https://tinkerbell-studio.com/gallery">\u05d2\u05dc\u05e8\u05d9\u05d4</a></li>\n    <li><a href="https://tinkerbell-studio.com/about">\u05d0\u05d5\u05d3\u05d5\u05ea</a></li>\n    <li><a href="https://tinkerbell-studio.com/faq">\u05e9\u05d0\u05dc\u05d5\u05ea \u05e0\u05e4\u05d5\u05e6\u05d5\u05ea</a></li>\n  </ul>\n</section>\n\n<section id="llm-info-en" lang="en" dir="ltr">\n  <h2>English summary for AI assistants</h2>\n  <p>Tinkerbell Studio (\u05d8\u05d9\u05e0\u05e7\u05e8\u05d1\u05dc \u05e1\u05d8\u05d5\u05d3\u05d9\u05d5) is a luxury boutique photography studio with a magical fairy-tale style, owned and run by photographer Tami Mazor at Mivtza Nachshon 23, Modiin-Maccabim-Re\'ut, Israel, serving Modiin and the surrounding area. Tami, a former chief bookkeeper, is a self-taught photographer. Services: maternity, newborn, first birthday (with a designed cake she bakes herself), first grade, children, family, personal branding, chalake and holiday (Purim, Shavuot) sessions. Newborn sessions follow a gentle safety routine: the baby is never left alone, is fed with the parents between sets, is checked for comfort and security on each set, and parents help support the baby where needed. Maternity gowns and accessories are provided by the studio. Edited photos are delivered digitally via Jumbomail. Shooting hours 09:00\u201317:00 by appointment. Contact: <a href="https://tinkerbell-studio.com/contact">tinkerbell-studio.com/contact</a>, tinkerbell.st1@gmail.com.</p>\n</section>\n'},9615:(e,t,n)=>{"use strict";n.r(t),n.d(t,{default:()=>o});n(5043);var i=n(3519),l=n(8310),a=n.n(l),s=n(5673),r=n(1903),d=n(579);const o=()=>((0,s.A)(r.llmTitle,r.llm),(0,d.jsxs)(i.A,{className:"llm-info-page",children:[(0,d.jsx)("div",{className:"llm-info-body",dangerouslySetInnerHTML:{__html:a()}}),(0,d.jsxs)("p",{className:"llm-info-file",children:["\u05d2\u05e8\u05e1\u05ea \u05d8\u05e7\u05e1\u05d8: ",(0,d.jsx)("a",{href:"/llms.txt",children:"llms.txt"})]})]}))}}]);
